import json, re, pathlib, collections
manifest = '/mnt/data/LSF/results/financebench/agentic_rule_full_data_gpt54mini/all_docs/q03_what_is_total_revenue_for_the_most_recent_fiscal_year_from_t.manifest.json'
with open(manifest) as f:
    obj = json.load(f)
docs = obj['documents']
head_re = re.compile(r'consolidated statements of (income|operations)|condensed consolidated statements of (income|operations)|statements of (income|operations)', re.I)
label_counts = collections.Counter()
examples = {}
for d in docs:
    path = pathlib.Path(d['doc_path'])
    try:
        lines = path.read_text(errors='ignore').splitlines()
    except Exception:
        continue
    for i, line in enumerate(lines):
        if head_re.search(line):
            # find first line after heading that looks like a revenue row label
            for j in range(i+1, min(len(lines), i+25)):
                s = lines[j].strip()
                if not s:
                    continue
                if re.fullmatch(r'(revenue:?|net sales|net revenue|total revenue|product sales|sales)', s, re.I):
                    label = s.lower()
                    label_counts[label] += 1
                    examples.setdefault(label, []).append((d['doc_name'], j+1, s))
                    break
            break
print('LABEL COUNTS')
for k,v in label_counts.most_common():
    print(v, k)
print('EXAMPLES')
for k,v in examples.items():
    print(k, v[:3])
