def rule_row_header_revenue_generic(doc: dict) -> list[dict]:
    """Match tables with a first-column row mentioning revenue or sales near the top of the table."""
    try:
        out = []
        for span in doc.get("texts", []):
            if span.get("label") != "table":
                continue
            cells = ((span.get("table_data") or {}).get("cells") or [])
            for c in cells:
                row = c.get("row", 999)
                col = c.get("col", 999)
                txt = (c.get("text") or "").strip().lower()
                if row <= 5 and col <= 1 and any(k in txt for k in ["revenue", "revenues", "sales"]):
                    out.append(span)
                    break
        return out
    except Exception:
        return []

def rule_consolidated_statement_of_income_heading(doc: dict) -> list[dict]:
    """Match section headers naming Consolidated Statement(s) of Income."""
    try:
        out = []
        for span in doc.get("texts", []):
            if span.get("label") != "section_header":
                continue
            txt = (span.get("text") or "").lower()
            if "consolidated statement of income" in txt or "consolidated statements of income" in txt:
                out.append(span)
        return out
    except Exception:
        return []

import re


def rule_income_statement_net_income_window(doc: dict) -> list[dict]:
    try:
        lines = [ln for ln in (doc.get("lines") or []) if isinstance(ln, dict)]
        if not lines:
            return []

        def norm(text: str) -> str:
            return re.sub(r"\s+", " ", (text or "").replace("\xa0", " ")).strip()

        ordered = sorted(
            lines,
            key=lambda ln: (
                int(ln.get("page_no") or 0),
                int(ln.get("line_no") or 0),
            ),
        )

        label_re = re.compile(
            r"\b(?:"
            r"consolidated\s+net\s+(?:income|earnings)(?:\s*\(loss\))?(?:\s+attributable\s+to\b(?!\s*noncontrolling\b).*)?|"
            r"net\s+(?:income|earnings)(?:\s*\(loss\))?(?!\s+per\s+share)(?:\s+attributable\s+to\b(?!\s*noncontrolling\b).*)?|"
            r"net\s+loss(?:\s+attributable\s+to\b(?!\s*noncontrolling\b).*)?"
            r")\b",
            re.IGNORECASE,
        )
        numeric_re = re.compile(r"^[\s$\-(),.\d\u2013\u2014]+$")
        year_re = re.compile(r"\b(?:19|20)\d{2}\b|\byear ended\b", re.IGNORECASE)

        def is_numericish(text: str) -> bool:
            low = norm(text)
            return bool(low) and (bool(numeric_re.fullmatch(low)) or bool(year_re.search(low)))

        def is_context(text: str) -> bool:
            low = norm(text)
            if not low:
                return False
            if is_numericish(low):
                return True
            if re.match(
                r"^(?:less:|total|net income|net earnings|net loss|"
                r"consolidated net income|adjustments to reconcile|"
                r"basic net income|diluted net income|shares used to compute|"
                r"year ended|years ended|fiscal year|trailing twelve months|"
                r"calculation of return on assets|return on assets|"
                r"calculation of return on investment|return on investment|"
                r"selected financial data|other financial measures|"
                r"net income per share|earnings per share)",
                low,
                re.IGNORECASE,
            ):
                return True
            if len(low.split()) <= 4 and re.fullmatch(r"[\d,().$\-\s]+", low):
                return True
            return False

        candidates = []
        seen = set()

        for i, ln in enumerate(ordered):
            text = norm(ln.get("text"))
            if not text:
                continue

            low = text.lower()
            if "table of contents" in low:
                continue

            joined = " ".join(
                norm(ordered[j].get("text"))
                for j in range(i, min(len(ordered), i + 3))
                if norm(ordered[j].get("text"))
            )
            if not joined or not (label_re.search(text) or label_re.search(joined)):
                continue

            has_numeric_neighbor = any(
                is_numericish(norm(ordered[j].get("text")))
                for j in range(i + 1, min(len(ordered), i + 5))
            )
            if not has_numeric_neighbor:
                continue

            context_start = max(0, i - 20)
            context_end = min(len(ordered), i + 20)
            context_text = " ".join(
                norm(ordered[j].get("text"))
                for j in range(context_start, context_end)
                if norm(ordered[j].get("text"))
            )
            context_low = context_text.lower()

            score = 0
            if re.search(r"\btrailing twelve months\b", context_low):
                score += 120
            if re.search(r"\b(?:for the )?(?:year|years) ended\b|\bfiscal year\b", context_low):
                score += 100
            if re.search(
                r"\b(?:consolidated|condensed)?\s*statements?\s+of\s+"
                r"(?:income(?:\s*\(loss\))?|operations(?:\s*\(loss\))?|earnings(?:\s*\(loss\))?|comprehensive\s+income(?:\s*\(loss\))?)",
                context_low,
            ) or re.search(
                r"\b(?:consolidated|condensed)?\s*statement\s+of\s+"
                r"(?:income(?:\s*\(loss\))?|operations(?:\s*\(loss\))?|earnings(?:\s*\(loss\))?|comprehensive\s+income(?:\s*\(loss\))?)",
                context_low,
            ):
                score += 85
            if re.search(r"\bcalculation of return on assets\b|\breturn on assets\b", context_low):
                score += 95
            if re.search(r"\bcalculation of return on investment\b|\breturn on investment\b", context_low):
                score += 90
            if re.search(r"\bnet income per share\b|\bearnings per share\b", context_low):
                score += 65
            if re.search(r"\bselected financial data\b|\bother financial measures\b", context_low):
                score += 40
            if re.search(
                r"\bnet income from continuing operations\b|\bnet loss from discontinued operations\b",
                context_low,
            ):
                score += 130
            if re.search(r"\badjusted net income\b", context_low):
                continue
            if re.search(r"\bthree months ended\b|\bsix months ended\b|\bquarterly period ended\b", context_low):
                score -= 80
            if re.search(r"\bcash flows from operating activities\b|\badjustments to reconcile net income\b", context_low):
                score -= 35
            if re.search(r"\btable of contents\b", context_low):
                score -= 80

            if re.search(r"\bwas\b|\bwere\b", low):
                score -= 20

            if re.fullmatch(r"net income(?:\s*\(loss\))?", low):
                score += 55
            elif re.fullmatch(r"net earnings(?:\s*\(loss\))?", low):
                score += 50
            elif low.startswith("consolidated net income"):
                score += 48
            elif low.startswith("net income"):
                score += 40
            elif low.startswith("net earnings"):
                score += 38
            elif low.startswith("net loss"):
                score += 32

            word_count = len(re.findall(r"[A-Za-z]+(?:'[A-Za-z]+)?", text))
            if word_count > 10 and re.search(r"\bwas\b|\bwere\b", low):
                continue
            if word_count > 12 and not low.startswith(
                (
                    "net income",
                    "net earnings",
                    "consolidated net income",
                    "net loss",
                )
            ):
                continue
            if word_count <= 5 and " was " not in f" {low} " and " were " not in f" {low} ":
                score += 20
            elif word_count > 12:
                score -= 12

            if "noncontrolling" in context_low:
                score -= 35
            if "attributable" in low and "noncontrolling" not in low:
                score -= 100
            if "attributable" in low and "noncontrolling" in low:
                score -= 20
            if re.search(r"\b\d{4}\b", context_low):
                score += 12

            if score <= 0 and not re.search(r"\byear ended\b|\bfiscal year\b|\btrailing twelve months\b", context_low):
                continue

            start = max(0, i - 2)
            end = min(len(ordered), i + 6)
            snippet_lines = []
            for j in range(start, end):
                t = norm(ordered[j].get("text"))
                if not t:
                    continue
                if j == i or is_context(t) or label_re.search(t):
                    snippet_lines.append(t)

            snippet = "\n".join(snippet_lines).strip()
            if not snippet or not any(ch.isdigit() for ch in snippet):
                continue

            key = snippet.lower()
            if key in seen:
                continue
            seen.add(key)
            candidates.append((score, i, snippet))

        if not candidates:
            return []

        candidates.sort(key=lambda item: (-item[0], item[1], len(item[2])))
        out = []
        seen_out = set()
        for _, i, snippet in candidates:
            if snippet in seen_out:
                continue
            seen_out.add(snippet)
            ln = ordered[i]
            out.append(
                {
                    "page_no": ln.get("page_no"),
                    "line_no": ln.get("line_no"),
                    "text": snippet,
                }
            )
            if len(out) >= 3:
                break

        return out
    except Exception:
        return []

import re


def rule_long_term_debt_line_window(doc: dict) -> list[dict]:
    try:
        out = []
        seen = set()
        kw_re = re.compile(
            r"("
            r"long[- ]term debt and obligations under finance leases|"
            r"long[- ]term debt and finance lease obligations|"
            r"long[- ]term debt and obligations|"
            r"long[- ]term debt obligations|"
            r"long[- ]term debt due within one year|"
            r"current portion of (?:debt|long[- ]term debt)(?: and obligations under finance leases)?|"
            r"debt and obligations under finance leases|"
            r"carrying value of long[- ]term debt|"
            r"long[- ]term obligations|"
            r"long[- ]term debt|"
            r"total debt outstanding|"
            r"debt and borrowings"
            r")",
            re.IGNORECASE,
        )
        row_start_re = re.compile(
            r"^\s*(?:"
            r"long[- ]term debt(?:\b|,|$| and obligations under finance leases| and finance lease obligations|"
            r" and obligations| obligations| due within one year|, including amounts due within one year)|"
            r"current portion of (?:debt|long[- ]term debt)(?: and obligations under finance leases)?|"
            r"debt and obligations under finance leases|"
            r"carrying value of long[- ]term debt|"
            r"long[- ]term obligations|"
            r"total debt outstanding"
            r")",
            re.IGNORECASE,
        )
        short_row_re = re.compile(r"^\s*(?:\$|[()\d,.\-]+|\s)+\s*$")
        date_header_re = re.compile(
            r"(?:\b(?:jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\b|\b20\d{2}\b|\b19\d{2}\b|"
            r"december\s+31,|june\s+30,|april\s+30,|january\s+31,|may\s+31,|march\s+31,|"
            r"september\s+30,|august\s+31,|february\s+28,|february\s+29,|year ended)",
            re.IGNORECASE,
        )
        continuation_re = re.compile(
            r"^(?:within one year|due within one year|current portion(?: of(?: long[- ]term)? debt)?|"
            r"thereafter|less: current portion.*|total|balances as of .+)$",
            re.IGNORECASE,
        )

        def alpha_word_count(text: str) -> int:
            return len(re.findall(r"[A-Za-z]+(?:'[A-Za-z]+)?", text))

        def is_row_like(text: str) -> bool:
            low = text.lower().strip()
            if not low:
                return False
            if row_start_re.search(low):
                return alpha_word_count(low) <= 12
            return False

        def is_context_line(text: str) -> bool:
            low = text.lower().strip()
            if not low:
                return False
            if short_row_re.match(low):
                return True
            if re.fullmatch(r"[\d,().$\-\s]+", low):
                return True
            if date_header_re.search(low):
                return alpha_word_count(low) <= 12
            if continuation_re.match(low):
                return True
            return False

        by_page = {}
        for line in doc.get("lines") or []:
            by_page.setdefault(line.get("page_no"), []).append(line)

        for page_no, page_lines in by_page.items():
            for idx, line in enumerate(page_lines):
                text = str(line.get("text") or "").strip()
                if not text or not is_row_like(text):
                    continue

                start = max(0, idx - 12)
                end = min(len(page_lines), idx + 4)
                snippet_lines = []
                for item in page_lines[start:end]:
                    item_text = str(item.get("text") or "").strip()
                    if item_text and is_context_line(item_text):
                        snippet_lines.append(item_text)

                snippet = "\n".join(snippet_lines).strip()
                if not snippet:
                    continue

                key = (page_no, line.get("line_no"), snippet)
                if key in seen:
                    continue
                seen.add(key)
                out.append(
                    {
                        "page_no": page_no,
                        "line_no": line.get("line_no"),
                        "text": snippet,
                    }
                )

        return out
    except Exception:
        return []

def rule_item8_revenue_rows_in_tables(doc: dict) -> list[dict]:
    """Match Item 8 tables containing revenue-like row labels such as net sales, net revenues, or revenue."""
    try:
        out = []
        for span in doc.get("texts", []):
            if span.get("label") != "table":
                continue
            path = (span.get("structure", {}) or {}).get("path_text", "") or ""
            if "Item 8" not in path and "Financial Statements" not in path and "Supplementary Data" not in path:
                continue
            cells = ((span.get("table_data") or {}).get("cells") or [])
            row_texts = {}
            for c in cells:
                row = c.get("row")
                row_texts.setdefault(row, []).append((c.get("text") or "").strip())
            found = False
            for parts in row_texts.values():
                row_join = " | ".join(parts).lower()
                if any(k in row_join for k in [
                    "net sales", "net revenues", "total revenue", "total revenues",
                    "revenue", "revenues", "sales"
                ]):
                    found = True
                    break
            if found:
                out.append(span)
        return out
    except Exception:
        return []

def rule_row_header_net_revenues(doc: dict) -> list[dict]:
    """Match tables containing a row header for net revenues."""
    try:
        out = []
        for span in doc.get("texts", []):
            if span.get("label") != "table":
                continue
            cells = ((span.get("table_data") or {}).get("cells") or [])
            for c in cells:
                txt = (c.get("text") or "").strip().lower()
                if txt in {"net revenues", "net revenue"}:
                    out.append(span)
                    break
        return out
    except Exception:
        return []

def rule_top_row_revenue_in_income_tables(doc: dict) -> list[dict]:
    """Match income-statement tables where the revenue row appears in the first few rows."""
    try:
        out = []
        for span in doc.get("texts", []):
            if span.get("label") != "table":
                continue
            txt = ((span.get("text") or "") + " " + ((span.get("structure", {}) or {}).get("path_text", "") or "")).lower()
            if not any(k in txt for k in ["income", "operations", "earnings"]):
                continue
            cells = ((span.get("table_data") or {}).get("cells") or [])
            rows = {}
            for c in cells:
                rows.setdefault(c.get("row"), []).append(c)
            for row_num, row_cells in rows.items():
                if row_num is None or row_num > 4:
                    continue
                row_join = " | ".join((c.get("text") or "") for c in row_cells).lower()
                if any(k in row_join for k in ["net sales", "net revenues", "total revenue", "revenue", "sales"]):
                    out.append(span)
                    break
        return out
    except Exception:
        return []

    return coerced


def _span_key(span: dict[str, Any]) -> tuple[Any, ...]:
    return (
        span.get("page_no"),
        span.get("paragraph_no"),
        span.get("line_no"),
        span.get("text"),
    )


def _sort_key(span: dict[str, Any]) -> tuple[Any, ...]:
    return (
        span.get("page_no", 10**9),
        span.get("paragraph_no", 10**9),
        span.get("line_no", 10**9),
        span.get("text", ""),
    )


def _list_rule_files(rules_dir: Path, rule_names: list[str] | None = None) -> list[Path]:
    if rule_names:
        files = [rules_dir / f"{name}.py" for name in rule_names]
        return [path for path in files if path.exists()]
    return sorted(path for path in rules_dir.glob("rule_*.py") if path.is_file())


def _apply_rule_files(document: dict[str, Any], rule_files: list[Path]) -> dict[str, Any]:
    spans: list[dict[str, Any]] = []
    rules_applied: list[str] = []
    rules_no_hits: list[str] = []
    rule_errors: list[str] = []

    for rule_file in rule_files:
        rule_name = rule_file.stem
        try:
            rule_fn = _load_rule_fn(rule_file)
            raw_result = rule_fn(document)
        except Exception as exc:
            rule_errors.append(f"{rule_name}: {exc}")
            rules_no_hits.append(rule_name)
            continue

        if not isinstance(raw_result, list):
            rules_no_hits.append(rule_name)
            continue

        coerced = [_coerce_span(item) for item in raw_result]
        cleaned = [item for item in coerced if item]
        if cleaned:
            spans.extend(cleaned)
            rules_applied.append(rule_name)
        else:
            rules_no_hits.append(rule_name)

    deduped: list[dict[str, Any]] = []
    seen: set[tuple[Any, ...]] = set()
    for span in spans:
        key = _span_key(span)
        if key in seen:
            continue
        seen.add(key)
        deduped.append(span)

    deduped.sort(key=_sort_key)
    retrieved_text = "\n\n".join(span["text"] for span in deduped) if deduped else ""

    return {
        "retrieved_spans": deduped,
        "retrieved_text": retrieved_text,
        "retrieved_token_count": _count_tokens(retrieved_text),
        "rules_applied": rules_applied,
        "rules_no_hits": rules_no_hits,
        "rule_errors": rule_errors,
    }


def _qa_call(question: str, retrieved_text: str, *, model_name: str = "gpt54") -> tuple[str | None, int, int, float]:
    model_mod = importlib.import_module(f"models.{model_name}")
    t0 = time.time()
    response = model_mod.client.chat.completions.create(
        model=model_mod.AZURE_DEPLOYMENT,
        messages=[
            {"role": "system", "content": _QA_SYSTEM},
            {"role": "user", "content": f"Passage:\n{retrieved_text}\n\nQuestion: {question}"},
        ],
        max_completion_tokens=500,
        temperature=0.0,
    )
    latency = round(time.time() - t0, 3)
    answer = (response.choices[0].message.content or "").strip() or None
    usage = response.usage
    return (
        answer,
        int(usage.prompt_tokens if usage else 0),
        int(usage.completion_tokens if usage else 0),
        latency,
    )


def _judge_call(
    dataset_name: str,
    question: str,
    ground_truth: Any,
    predicted: Any,
) -> tuple[bool, int, int]:
    if ground_truth is None or predicted is None:
        return False, 0, 0

    model_mod = importlib.import_module("models.gpt54")
    gt_str = json.dumps(ground_truth) if not isinstance(ground_truth, str) else ground_truth
    pred_str = str(predicted)
    response = model_mod.client.chat.completions.create(
        model=model_mod.AZURE_DEPLOYMENT,
        messages=[
            {
                "role": "system",
                "content": _JUDGE_SYSTEM_BY_DATASET.get(dataset_name, _JUDGE_SYSTEM_GENERIC),
            },
            {
                "role": "user",
                "content": f"Question: {question}\nGround Truth: {gt_str}\nPredicted: {pred_str}",
            },
        ],
        max_completion_tokens=10,
        temperature=0.0,
    )
    verdict = (response.choices[0].message.content or "").strip().lower()
    usage = response.usage
    return (
        verdict == "correct",
        int(usage.prompt_tokens if usage else 0),
        int(usage.completion_tokens if usage else 0),
    )


def _clean_stderr(stderr: str) -> str:
    lines = [
        line
        for line in stderr.splitlines()
        if line.strip() != "Reading additional input from stdin..."
    ]
    return "\n".join(lines).strip()[:4000]


def _parse_done_output(text: str) -> str | None:
    for line in text.splitlines():
        line = line.strip()
        if line.startswith("AGENTIC_RULE_FULL_DATA_DONE"):
            rest = line[len("AGENTIC_RULE_FULL_DATA_DONE") :].strip()
            if rest.startswith("report="):
                return rest[len("report=") :].strip()
    return None


def _parse_codex_events(jsonl_text: str) -> dict[str, Any]:
    usage_totals = {
        "input_tokens": 0,
        "output_tokens": 0,
        "cached_input_tokens": 0,
        "reasoning_output_tokens": 0,
    }
    thread_id: str | None = None
    error_message: str | None = None
    event_count = 0

    for raw_line in jsonl_text.splitlines():
        raw_line = raw_line.strip()
        if not raw_line:
            continue
        try:
            event = json.loads(raw_line)
        except json.JSONDecodeError:
            continue
        event_count += 1
        if event.get("type") == "thread.started":
            thread_id = event.get("thread_id")
        elif event.get("type") == "turn.completed":
            usage = event.get("usage") or {}
            for key in usage_totals:
                usage_totals[key] += int(usage.get(key) or 0)
        elif event.get("type") in {"error", "turn.failed"}:
            error_message = event.get("message") or str(event.get("error") or "")

    return {
        "usage_totals": usage_totals,
        "thread_id": thread_id,
        "error_message": error_message,
        "event_count": event_count,
    }


def _load_json(path: Path, default: Any) -> Any:
    if not path.exists():
        return default
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return default


def _write_json(path: Path, payload: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(payload, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")


def _relpath(path: Path) -> str:
    try:
        return str(path.relative_to(_ROOT))
    except ValueError:
        return str(path)


def _ledger_load(ledger_path: Path) -> dict[str, Any]:
    return _load_json(ledger_path, {"verify_accuracy_calls": []})


def _ledger_append_verify(ledger_path: Path, entry: dict[str, Any]) -> dict[str, Any]:
    ledger = _ledger_load(ledger_path)
    calls = ledger.setdefault("verify_accuracy_calls", [])
    calls.append(entry)
    _write_json(ledger_path, ledger)
    return ledger


def _manifest_docs(manifest: dict[str, Any]) -> dict[str, Path]:
    return {
        entry["doc_name"]: Path(entry["doc_path"])
        for entry in manifest.get("documents", [])
    }


def _manifest_ground_truth(manifest: dict[str, Any]) -> dict[str, Any]:
    return {
        entry["doc_name"]: entry.get("ground_truth")
        for entry in manifest.get("documents", [])
    }


def _verify_accuracy_on_docs(
    *,
    manifest: dict[str, Any],
    doc_names: list[str],
    rule_names: list[str] | None = None,
) -> dict[str, Any]:
    docs_map = _manifest_docs(manifest)
    gt_map = _manifest_ground_truth(manifest)
    rules_dir = Path(manifest["rules_dir"])
    question = manifest["question"]
    dataset_name = manifest["dataset"]
    rule_files = _list_rule_files(rules_dir, rule_names)

    results: list[dict[str, Any]] = []
    total_qa_in = 0
    total_qa_out = 0
    total_judge_in = 0
    total_judge_out = 0
    total_latency = 0.0
    cost_ratios: list[float] = []

    for doc_name in doc_names:
        doc_path = docs_map[doc_name]
        document = _load_txt_doc(doc_name, doc_path)
        applied = _apply_rule_files(document, rule_files)
        answer, qa_in, qa_out, latency = _qa_call(question, applied["retrieved_text"], model_name="gpt54")
        correct, judge_in, judge_out = _judge_call(dataset_name, question, gt_map.get(doc_name), answer)
        doc_tokens = _count_tokens(document["text"])
        cost_ratio = applied["retrieved_token_count"] / doc_tokens if doc_tokens > 0 else 0.0

        total_qa_in += qa_in
        total_qa_out += qa_out
        total_judge_in += judge_in
        total_judge_out += judge_out
        total_latency += latency
        cost_ratios.append(cost_ratio)

        results.append(
            {
                "doc_name": doc_name,
                "answer": answer,
                "correct": correct,
                "retrieved_token_count": applied["retrieved_token_count"],
                "cost_ratio": round(cost_ratio, 6),
                "rules_applied": applied["rules_applied"],
            }
        )

    n = len(results)
    n_correct = sum(1 for item in results if item["correct"])
    accuracy = (n_correct / n) if n else 0.0
    return {
        "doc_names": doc_names,
        "rule_names": [path.stem for path in rule_files],
        "n": n,
        "n_correct": n_correct,
        "accuracy": round(accuracy, 6),
        "avg_cost_ratio": round(sum(cost_ratios) / n, 6) if n else 0.0,
